sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_instances;
uniform float amzp_repMode;
uniform float amzp_showOrig;
uniform float2 amzp_posOff;
uniform float amzp_zOff;
uniform float amzp_rotX;
uniform float amzp_rotY;
uniform float amzp_rotZ;
uniform float amzp_scaleStep;
uniform float amzp_endOpacity;
layout(color) uniform half4 amzp_startCol;
layout(color) uniform half4 amzp_endCol;
uniform float amzp_colorMix;
uniform float amzp_drawOrder;
uniform float amzp_camMode;
uniform float amzp_camTilt;
uniform float amzp_camPan;
uniform float amzp_camZoom;
uniform float amzp_overdrawOn;
    uniform float4x4 nmModel;
    uniform float4x4 nmView;
    uniform float4x4 nmProj;
    float4x4 VM, PM;
    bool SCN;
    float GPS;
    float camOK() { return (nmProj[2][3] > 0.5 && abs(nmProj[0][0]) + abs(nmProj[1][1]) > 1e-6) ? 1.0 : 0.0; }
    void setupCam(bool useScene, float tilt, float pan, float zoom, float3 cpos) {
        SCN = useScene && camOK() > 0.5;
        if (SCN) { VM = nmView; PM = nmProj; return; }
        float t = radians(tilt), p = radians(pan);
        float3 fwd = float3(sin(p) * cos(t), sin(t), cos(p) * cos(t));
        float3 right = float3(cos(p), 0.0, -sin(p));
        float3 down = cross(fwd, right);
        VM = float4x4(float4(right.x, down.x, fwd.x, 0.0), float4(right.y, down.y, fwd.y, 0.0), float4(right.z, down.z, fwd.z, 0.0),
                  float4(-dot(right, cpos), -dot(down, cpos), -dot(fwd, cpos), 1.0));
        float z = max(zoom, 1.0);
        PM = float4x4(float4(z, 0.0, 0.0, 0.0), float4(0.0, z, 0.0, 0.0), float4(0.0, 0.0, 0.0, 1.0), float4(0.0, 0.0, 1.0, 0.0));
    }
    float3 rayDir(float2 q) {
        float3 r0 = float3(PM[0][0], PM[1][0], PM[2][0]);
        float3 r1 = float3(PM[0][1], PM[1][1], PM[2][1]);
        float3 rw = float3(PM[0][3], PM[1][3], PM[2][3]);
        float3 d = cross(r0 - q.x * rw, r1 - q.y * rw);
        if (d.z < 0.0) d = -d;
        float3 c0 = VM[0].xyz, c1 = VM[1].xyz, c2 = VM[2].xyz;
        float3 w = float3(dot(c0, d) / max(dot(c0, c0), 1e-8), dot(c1, d) / max(dot(c1, c1), 1e-8), dot(c2, d) / max(dot(c2, c2), 1e-8));
        return normalize(w);
    }
    float3 camPos() {
        float3 c0 = VM[0].xyz, c1 = VM[1].xyz, c2 = VM[2].xyz;
        float3 t = VM[3].xyz;
        return -float3(dot(c0, t) / max(dot(c0, c0), 1e-8), dot(c1, t) / max(dot(c1, c1), 1e-8), dot(c2, t) / max(dot(c2, c2), 1e-8));
    }
    float3 toScreen(float3 p) {
        float4 c = PM * (VM * float4(p, 1.0));
        if (c.w <= 1e-6) return float3(0.0, 0.0, -1.0);
        float2 q = c.xy / c.w;
        float2 pix = q * GPS + screen.zw * 0.5;
        return float3(pix.x / screen.zw.x, 1.0 - pix.y / screen.zw.y, 1.0);
    }
    float2 fragQ() {
        GPS = screen.zw.y / max(screen.zw.y, 1.0);
        float2 pix = float2(amzScreenNorm().x, 1.0 - amzScreenNorm().y) * screen.zw;
        return (pix - screen.zw * 0.5) / GPS;
    }
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float4 scr(float2 uv) {
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return float4(0.0);
        return amzTexture(0, uv);
    }
    float4 layerTex(float2 uv) {
        if (uv.x < 0.0 || uv.x > 1.0 || uv.y < 0.0 || uv.y > 1.0) return float4(0.0);
        return scr(l2s(uv));
    }
    float3 MO, MX, MY, MZ;
    void setupModel(float2 qc) {
        MX = float3(1.0, 0.0, 0.0); MY = float3(0.0, 1.0, 0.0); MZ = float3(0.0, 0.0, 1.0);
        MO = float3(qc, 0.0);
        if (!SCN) return;
        float3 mx = nmModel[0].xyz, my = nmModel[1].xyz, mz = nmModel[2].xyz;
        float lx = length(mx), ly = length(my), lz = length(mz);
        float det = dot(mx, cross(my, mz));
        if (!(lx > 1e-6 && ly > 1e-6 && lz > 1e-6 && abs(det) > 1e-9 && abs(nmModel[3][3] - 1.0) < 0.01)) return;
        MX = mx; MY = my; MZ = mz / lz * 0.5 * (lx + ly);
        MO = nmModel[3].xyz;
    }
    float3x3 rotXYZ(float3 a) {
        float3 c = cos(a), s = sin(a);
        float3x3 rx = float3x3(1.0, 0.0, 0.0, 0.0, c.x, s.x, 0.0, -s.x, c.x);
        float3x3 ry = float3x3(c.y, 0.0, -s.y, 0.0, 1.0, 0.0, s.y, 0.0, c.y);
        float3x3 rz = float3x3(c.z, s.z, 0.0, -s.z, c.z, 0.0, 0.0, 0.0, 1.0);
        return rz * ry * rx;
    }
    void nmFxMain() {
        float4 orig = scr(amzScreenNorm());
        float2 q = fragQ();
        setupCam(int(amzp_camMode) == 0, amzp_camTilt, amzp_camPan, amzp_camZoom, float3(0.0, 0.0, -max(amzp_camZoom, 1.0)));
        float4 cs = float4(0.5, 0.5, 0.0, 1.0) * amzLayerToScreen();
        float2 qc = (float2(cs.x, 1.0 - cs.y) * screen.zw - screen.zw * 0.5) / GPS;
        setupModel(qc);
        float3 ro = camPos();
        float3 rd = rayDir(q);
        float3x3 B = float3x3(MX, MY, MZ);
        float N = floor(clamp(amzp_instances, 1.0, 64.0) + 0.5);
        float3 stepT = float3(amzp_posOff, amzp_zOff);
        float3x3 stepR = rotXYZ(radians(float3(amzp_rotX, amzp_rotY, amzp_rotZ)));
        float ss = max(amzp_scaleStep, 0.001);
        bool firstTop = true;
        if (int(amzp_drawOrder) == 2) firstTop = false;
        else if (int(amzp_drawOrder) == 0) {
            float3 tl = float3(0.0); float3x3 rl = float3x3(1.0); float sl = 1.0;
            for (int i = 1; i < 64; i++) {
                if (float(i) >= N) break;
                if (int(amzp_repMode) == 1) { tl += rl * stepT * sl; rl = rl * stepR; sl *= ss; }
                else tl = stepT * float(i);
            }
            float4 v0 = VM * float4(MO, 1.0);
            float4 v1 = VM * float4(MO + B * tl, 1.0);
            firstTop = v0.z <= v1.z;
        }
        float4 acc = float4(0.0);
        float3 t = float3(0.0);
        float3x3 R = float3x3(1.0);
        float sc = 1.0;
        for (int i = 0; i < 64; i++) {
            float fi = float(i);
            if (fi >= N) break;
            if (i > 0) {
                if (int(amzp_repMode) == 1) { t += R * stepT * sc; R = R * stepR; sc *= ss; }
                else { t = stepT * fi; R = rotXYZ(radians(float3(amzp_rotX, amzp_rotY, amzp_rotZ)) * fi); sc = pow(ss, fi); }
            }
            if (i == 0 && !(amzp_showOrig>0.5)) continue;
            float4 c = float4(0.0);
            if (i == 0) c = orig;
            else {
                float3 X = B * (R[0] * sc), Y = B * (R[1] * sc);
                float3 O = MO + B * t;
                float3 b = ro - O;
                float3 nr = -rd;
                float det = dot(X, cross(Y, nr));
                if (abs(det) < 1e-9) continue;
                float u = dot(b, cross(Y, nr)) / det;
                float v = dot(X, cross(b, nr)) / det;
                float s = dot(X, cross(Y, b)) / det;
                if (s <= 0.0) continue;
                float3 sp;
                if (SCN) sp = toScreen(MO + MX * u + MY * v);
                else {
                    float2 pq = MO.xy + float2(u, v);
                    float2 px = pq * GPS + screen.zw * 0.5;
                    sp = float3(px.x / screen.zw.x, 1.0 - px.y / screen.zw.y, 1.0);
                }
                if (sp.z < 0.0) continue;
                c = scr(sp.xy);
            }
            if (c.a <= 0.0001) continue;
            float g = N > 1.0 ? fi / (N - 1.0) : 0.0;
            float4 tc = mix(amzp_startCol, amzp_endCol, g);
            c.rgb = mix(c.rgb, c.rgb * tc.rgb, clamp(amzp_colorMix, 0.0, 1.0));
            c *= mix(1.0, tc.a, clamp(amzp_colorMix, 0.0, 1.0));
            c *= mix(1.0, clamp(amzp_endOpacity, 0.0, 1.0), g);
            if (firstTop) acc += c * (1.0 - acc.a);
            else acc = c + acc * (1.0 - c.a);
        }
        amzOutput = acc;
    }
    void amzRender() {
        nmFxMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
